(()=>{
const rates={QAR:1,USD:0.274725,EUR:0.2345,GBP:0.2045,AED:1.0088,SAR:1.0302,KWD:0.0839,BHD:0.1033,OMR:0.1057,TND:0.812908,MAD:2.63508};
const symbols={QAR:'QAR',USD:'$',EUR:'€',GBP:'£',AED:'AED',SAR:'SAR',KWD:'KWD',BHD:'BHD',OMR:'OMR',TND:'TND',MAD:'MAD'};
let currency=localStorage.getItem('sultana-currency')||'QAR';if(!rates[currency])currency='QAR';
const fmt=n=>{const v=n*rates[currency];return `${symbols[currency]} ${v.toLocaleString(undefined,{minimumFractionDigits:currency==='QAR'?0:2,maximumFractionDigits:2})}`};
const convertText=()=>document.querySelectorAll('.price,.detail-price,#bag-total,.cart-total,.cart-subtotal,.subtotal,.total,[data-price-display],[data-money]').forEach(el=>{if(!el.dataset.qar){const m=el.textContent.match(/QAR\s*([\d,.]+)/i);if(m)el.dataset.qar=m[1].replace(/,/g,'')}if(el.dataset.qar)el.textContent=fmt(Number(el.dataset.qar))});
const hideOldVisualMenu=()=>document.querySelectorAll('section').forEach(sec=>{const t=(sec.textContent||'').replace(/\s+/g,' ').toLowerCase();if((t.includes('explore sultana')||t.includes('discover our world'))&&t.includes('wedding')&&t.includes('hospitality'))sec.style.display='none'});
const installHeader=()=>{
 const h=document.querySelector('header');if(!h)return;
 let brand=h.querySelector(':scope > .brand');if(!brand){brand=document.createElement('a');brand.className='brand';brand.href='/';brand.setAttribute('aria-label','Sultana Perfumes home');brand.innerHTML='<img src="/assets/brand/sultana-logo.png" alt="Sultana Perfumes">';h.appendChild(brand)}
 let actions=h.querySelector(':scope > .header-actions');if(!actions){actions=document.createElement('div');actions.className='header-actions';h.appendChild(actions)}
 actions.innerHTML='<button class="icon-button" id="search-open" aria-label="Search fragrances"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4.5 4.5"/></svg></button><button class="icon-button" id="bag-open" aria-label="Open shopping bag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5.5 8.5h13l1 12h-15l1-12Z"/><path d="M9 9V6.5a3 3 0 0 1 6 0V9"/></svg><span class="header-bag-count">0</span></button>';
 let left=h.querySelector(':scope > .desktop-header-left');if(!left){left=document.createElement('div');left.className='desktop-header-left';h.appendChild(left)}
 left.innerHTML='<span>Qatar</span><span class="sep">|</span><select id="desktop-currency-select" aria-label="Currency"><option value="QAR">🇶🇦 QAR</option><option value="USD">🇺🇸 USD</option><option value="EUR">🇪🇺 EUR</option><option value="GBP">🇬🇧 GBP</option><option value="AED">🇦🇪 AED</option><option value="SAR">🇸🇦 SAR</option><option value="KWD">🇰🇼 KWD</option><option value="BHD">🇧🇭 BHD</option><option value="OMR">🇴🇲 OMR</option><option value="TND">🇹🇳 TND</option><option value="MAD">🇲🇦 MAD</option></select><span class="sep">|</span><a class="desktop-language-switch" href="/ar/" lang="ar">العربية</a>';left.querySelector('select').value=currency;
 let nav=h.querySelector(':scope > .desktop-luxury-nav');if(!nav){nav=document.createElement('nav');nav.className='desktop-luxury-nav';h.appendChild(nav)}
 nav.innerHTML='<a href="/">Home</a><a href="/shop/?collection=perfume#collection">Perfumes</a><a href="/room-sprays/">Luxury Spray</a><a href="/oud-bakhoor/">Oud &amp; Bakhoor</a><a href="/b2b/">B2B</a><a href="/our-story/">Our Story</a><a href="/contact/">Contact</a>';
 let style=document.getElementById('stable-global-header');if(!style){style=document.createElement('style');style.id='stable-global-header';document.head.appendChild(style)}
 style.textContent='@media(min-width:851px){header{height:160px!important;min-height:160px!important;padding:0 5%!important;display:grid!important;grid-template-columns:1fr auto 1fr!important;grid-template-rows:112px 48px!important;gap:0 24px!important;align-items:center!important;background:#fffdfa!important;position:relative!important;overflow:visible!important}header>.brand{display:block!important;grid-column:2!important;grid-row:1!important;justify-self:center!important;position:static!important;transform:none!important;width:92px!important;height:102px!important;margin:0!important}header>.brand img{display:block!important;width:100%!important;height:100%!important;object-fit:contain!important}header>.header-actions{grid-column:3!important;grid-row:1!important;justify-self:end!important;display:flex!important;visibility:visible!important;opacity:1!important;align-items:center!important;gap:18px!important;position:static!important;z-index:101!important}header>.header-actions .icon-button{display:inline-flex!important;visibility:visible!important;opacity:1!important;position:relative!important;width:34px!important;height:34px!important;align-items:center!important;justify-content:center!important;padding:5px!important;color:#17130f!important}header>.header-actions svg{display:block!important;width:24px!important;height:24px!important}.header-bag-count{position:absolute!important;top:0!important;right:-3px!important;min-width:15px!important;height:15px!important;background:#17130f!important;color:#fff!important;font:10px/15px Arial,sans-serif!important;text-align:center!important}header>#main-navigation,header>.menu-toggle{display:none!important}.desktop-header-left{grid-column:1!important;grid-row:1!important;justify-self:start!important;display:flex!important;visibility:visible!important;opacity:1!important;align-items:center!important;gap:11px!important;font-size:12px!important;white-space:nowrap!important}.desktop-header-left select,.desktop-header-left a{border:0!important;background:transparent!important;padding:4px 0!important;font-size:12px!important;color:#17130f!important;text-decoration:none!important}.desktop-header-left .sep{color:#9b9286!important}header>nav.desktop-luxury-nav{grid-column:1/-1!important;grid-row:2!important;display:flex!important;visibility:visible!important;opacity:1!important;position:relative!important;inset:auto!important;transform:none!important;width:100%!important;height:48px!important;align-items:center!important;justify-content:center!important;gap:clamp(25px,3vw,52px)!important;background:#fffdfa!important;z-index:100!important;margin:0!important;padding:0 20px!important}header>nav.desktop-luxury-nav>a{display:inline-flex!important;visibility:visible!important;opacity:1!important;align-items:center!important;height:48px!important;color:#17130f!important;font:500 11px/48px Arial,sans-serif!important;letter-spacing:.35px!important;text-transform:uppercase!important;white-space:nowrap!important;text-decoration:none!important;margin:0!important;padding:0!important}}@media(max-width:850px){.desktop-luxury-nav,.desktop-header-left{display:none!important}}';
};
const sync=()=>{installHeader();convertText();hideOldVisualMenu()};
document.addEventListener('change',e=>{if(e.target.id==='desktop-currency-select'||e.target.id==='currency-select'){currency=e.target.value;localStorage.setItem('sultana-currency',currency);document.querySelectorAll('#desktop-currency-select,#currency-select').forEach(s=>s.value=currency);convertText()}});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync);else sync();window.addEventListener('load',sync);setTimeout(sync,300);window.SultanaCurrency={formatQAR:fmt,get:()=>currency,refresh:sync};
})();